create table xxcus.xxcmp_rfis (
    rfi_id                     number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    rfi_number                 varchar2(30 byte) not null enable,
    entity_name                varchar2(60 byte) not null enable,
    pk1_value                  varchar2(150 byte) not null enable,
    response_task_id           number,
    review_task_id             number,
    recipient_type             varchar2(30 byte) not null enable,
    recipient_user_name        varchar2(255 byte),
    recipient_party_contact_id number,
    rfi_category               varchar2(30 byte) not null enable,
    description                varchar2(4000 byte) not null enable,
    continue_other_work_flag   varchar2(1 byte) not null enable,
    rfi_status                 varchar2(30 byte) default 'WAITING_FOR_INFORMATION' not null enable,
    due_date                   date,
    response_token_hash        varchar2(128 byte),
    token_expiry_date          timestamp(6),
    response_text              clob,
    responded_date             timestamp(6),
    resolved_date              timestamp(6),
    resolution_notes           varchar2(4000 byte),
    created_by                 varchar2(255 byte) not null enable,
    creation_date              timestamp(6) not null enable,
    last_updated_by            varchar2(255 byte) not null enable,
    last_update_date           timestamp(6) not null enable,
    last_update_login          varchar2(255 byte),
    object_version_number      number default 1 not null enable
);

alter table xxcus.xxcmp_rfis
    add constraint xxcmp_rfis_ck1
        check ( recipient_type in ( 'REQUESTING_DEPARTMENT', 'EXTERNAL_PARTY' ) ) enable;

alter table xxcus.xxcmp_rfis
    add constraint xxcmp_rfis_ck2
        check ( continue_other_work_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_rfis
    add constraint xxcmp_rfis_ck3
        check ( rfi_status in ( 'WAITING_FOR_INFORMATION', 'ON_HOLD_PENDING', 'ON_HOLD_INVESTIGATION', 'RESOLVED', 'REJECTED_RETURNED'
        ,
                                'CANCELLED' ) ) enable;

alter table xxcus.xxcmp_rfis
    add constraint xxcmp_rfis_ck4
        check ( ( recipient_type = 'REQUESTING_DEPARTMENT'
                  and recipient_user_name is not null )
                or ( recipient_type = 'EXTERNAL_PARTY'
                     and recipient_party_contact_id is not null ) ) enable;

alter table xxcus.xxcmp_rfis
    add constraint xxcmp_rfis_pk primary key ( rfi_id )
        using index enable;

alter table xxcus.xxcmp_rfis add constraint xxcmp_rfis_uk1 unique ( rfi_number )
    using index enable;


